static void rm_actor(FILE *f,const PathingEntity *e){assert((fgetc(f)!=0)==(e!=NULL));if(e){int v[]={e->primary_seq_id,e->primary_seq_frame,e->primary_seq_cycle,e->primary_seq_delay,e->primary_seq_loop,e->secondary_seq_id,e->secondary_seq_frame,e->secondary_seq_cycle};for(int i=0;i<8;i++)assert(rm_int(f)==v[i]);}}
